require "yaml"

MANUAL = {}

def edit(file, replacements, entries = {})
  path = file
  source = File.read(path)
  replacements.each do |from, to|
    raise "Not found in #{file}: #{from}" unless source.include?(from)
    source = source.sub(from, to)
  end
  File.write(path, source)
  scope = file.sub(%r{\Aapp/views/}, "").sub(%r{\.(html|text|turbo_stream|json|js|svg)\.erb\z}, "").sub(/\.erb\z/, "").gsub(%r{/_?}, ".")
  (MANUAL[scope] ||= {}).merge!(entries)
end
