# Translates the Ruby-side strings in app/helpers.
require "yaml"
require "fileutils"

ENTRIES = {}

def edit_file(path, replacements, scope: nil, entries: {})
  source = File.read(path)
  replacements.each do |from, to|
    next if source.include?(to)
    raise "Not found in #{path}: #{from}" unless source.include?(from)
    source = source.sub(from, to)
  end
  File.write(path, source)
  (ENTRIES[scope] ||= {}).merge!(entries) if scope
end

def add_entries(scope, entries)
  (ENTRIES[scope] ||= {}).merge!(entries)
end

